from solution import min_flip_to_make_string_alternate


def test_issue_example_from_issue():
    """Example '0001010111' needs 2 flips."""
    assert min_flip_to_make_string_alternate("0001010111") == 2  # min(2,8)=2


def test_issue_already_alternate_start_zero():
    """Alternate string '01010' needs 0 flips."""
    assert min_flip_to_make_string_alternate("01010") == 0  # min(0,5)=0


def test_issue_already_alternate_start_one():
    """Alternate string '10101' needs 0 flips."""
    assert min_flip_to_make_string_alternate("10101") == 0  # min(5,0)=0


def test_issue_empty_string():
    """Empty string needs 0 flips to be alternate."""
    assert min_flip_to_make_string_alternate("") == 0  # min(0,0)=0


def test_issue_single_char_zero():
    """Single char '0' needs 0 flips."""
    assert min_flip_to_make_string_alternate("0") == 0  # min(0,1)=0


def test_issue_single_char_one():
    """Single char '1' needs 0 flips."""
    assert min_flip_to_make_string_alternate("1") == 0  # min(1,0)=0


def test_issue_all_zeros_even_length():
    """String '0000' needs 2 flips to alternate."""
    assert min_flip_to_make_string_alternate("0000") == 2  # min(2,2)=2


def test_issue_all_ones_odd_length():
    """String '11111' needs 2 flips to alternate."""
    assert min_flip_to_make_string_alternate("11111") == 2  # min(3,2)=2


def test_issue_pair_same_needs_one():
    """String '00' needs 1 flip to alternate."""
    assert min_flip_to_make_string_alternate("00") == 1  # min(1,1)=1


def test_issue_pair_alternate_needs_zero():
    """String '01' needs 0 flips to alternate."""
    assert min_flip_to_make_string_alternate("01") == 0  # min(0,2)=0


def test_contract_minimum_prefers_pattern_starting_one():
    """Result must be minimum over both alternating patterns."""
    assert min_flip_to_make_string_alternate("111000") == 2  # min(4,2)=2


def test_contract_minimum_prefers_pattern_starting_zero():
    """Result must be minimum over both alternating patterns."""
    assert min_flip_to_make_string_alternate("000111") == 2  # min(2,4)=2
